package com.tracksphere.interfaces.rest;
import org.springframework.http.*; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { record ErrorResponse(Instant timestamp,int status,String error,Map<String,String> fields){} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e){Map<String,String> fields=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.put(x.getField(),x.getDefaultMessage()));return error(HttpStatus.BAD_REQUEST,"Validation failed",fields);}@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ErrorResponse> conflict(IllegalArgumentException e){return error(HttpStatus.CONFLICT,e.getMessage(),Map.of());}@ExceptionHandler(BadCredentialsException.class) ResponseEntity<ErrorResponse> unauthorized(BadCredentialsException e){return error(HttpStatus.UNAUTHORIZED,"Authentication failed",Map.of());} private ResponseEntity<ErrorResponse> error(HttpStatus status,String message,Map<String,String> fields){return ResponseEntity.status(status).body(new ErrorResponse(Instant.now(),status.value(),message,fields));} }
